-- 回滚：仅删除本迁移补齐的精确 (path,method) / (v0,v1,v2) 组合。
-- ⚠️ 与 2026-10-29-map-view-permissions 有重叠路径，两个迁移一起回滚才回到原状。
DELETE FROM sys_menu_api WHERE api_id IN (SELECT id FROM sys_api WHERE (BINARY path=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY method=BINARY 'GET') OR (BINARY path=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY method=BINARY 'PUT') OR (BINARY path=BINARY '/api/gb28181/device-mgmt/map/channel-tree' AND BINARY method=BINARY 'GET') OR (BINARY path=BINARY '/api/gb28181/device-mgmt/map/trajectory' AND BINARY method=BINARY 'GET') OR (BINARY path=BINARY '/api/sysJobResults/clear' AND BINARY method=BINARY 'POST'));
DELETE FROM sys_casbin_rule WHERE ptype='p' AND ((BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/config/viewCache' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/cascade/platforms/:id/disable' AND BINARY v2=BINARY 'POST') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/device/:id/catalog/refresh/:operationId' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/firmware-repository' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/firmware-repository' AND BINARY v2=BINARY 'POST') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/firmware-repository/:id' AND BINARY v2=BINARY 'DELETE') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/firmware-repository/:id' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/firmware-repository/:id/download-link' AND BINARY v2=BINARY 'POST') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/firmware-repository/:id/status' AND BINARY v2=BINARY 'PATCH') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY v2=BINARY 'PUT') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/channel-tree' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/trajectory' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/play/:deviceId/:channelId/authorization' AND BINARY v2=BINARY 'POST') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/sip/service-config' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/sip/service-config' AND BINARY v2=BINARY 'PUT') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/zlm/sessions/network' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/gb28181/zlm/sessions/viewers' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysJobResults/clear' AND BINARY v2=BINARY 'POST') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysMenu/:id' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysParam/:id' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysParam/add' AND BINARY v2=BINARY 'POST') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysParam/delete' AND BINARY v2=BINARY 'DELETE') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysParam/edit' AND BINARY v2=BINARY 'PUT') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysParam/getByCode/:code' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysParam/list' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysRole/:id' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/sysRole/list' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_1' AND BINARY v1=BINARY '/api/users/switchTenant/:tenantld' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_3' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_3' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/channel-tree' AND BINARY v2=BINARY 'GET') OR (BINARY v0=BINARY 'role_3' AND BINARY v1=BINARY '/api/gb28181/device-mgmt/map/trajectory' AND BINARY v2=BINARY 'GET'));
DELETE FROM sys_api WHERE (BINARY path=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY method=BINARY 'GET') OR (BINARY path=BINARY '/api/gb28181/device-mgmt/map/center' AND BINARY method=BINARY 'PUT') OR (BINARY path=BINARY '/api/gb28181/device-mgmt/map/channel-tree' AND BINARY method=BINARY 'GET') OR (BINARY path=BINARY '/api/gb28181/device-mgmt/map/trajectory' AND BINARY method=BINARY 'GET') OR (BINARY path=BINARY '/api/sysJobResults/clear' AND BINARY method=BINARY 'POST');
